@php
    $course = $course ?? null;
    $curriculum = old('curriculum_outline');
    if ($curriculum === null && !empty($course?->learning_outcomes)) {
        $decoded = is_array($course->learning_outcomes) ? $course->learning_outcomes : json_decode($course->learning_outcomes, true);
        $curriculum = collect($decoded ?: [])->map(function ($module) {
            return implode(' | ', array_merge([$module['name'] ?? ''], $module['topics'] ?? []));
        })->implode("\n");
    }
